//! Safe Rust bindings for the SwiftTunnel SDK.
//!
//! Generated by claude.ai, i aint doing this shit
//!
//! # Setup
//!
//! In your `build.rs`:
//! ```rust
//! fn main() {
//!     println!("cargo:rustc-link-search=native=libs");
//!     println!("cargo:rustc-link-lib=dylib=swifttunnel");
//! }
//! ```
//!
//! Place `swifttunnel.dll` in a `libs/` folder next to `Cargo.toml`.
//!
//! # Usage
//!
//! ```rust
//! let sdk = SwiftTunnel::init().unwrap();
//! sdk.auth_sign_in("user@example.com", "hunter2").unwrap();
//! sdk.connect_ex(ConnectOptions {
//!     region: "singapore".into(),
//!     apps: vec!["game.exe".into()],
//!     auto_routing: Some(AutoRouting {
//!         enabled: true,
//!         whitelisted_regions: vec!["US East".into()],
//!     }),
//! }).unwrap();
//! ```

